-- 自动透传检查的请求方向：mst_aw/mst_ar/mst_w是上游Master送入DUT的
-- 请求，slv_aw/slv_ar/slv_w是DUT送往下游Memory的请求。输入握手会形成
-- 一条期望记录，之后对应输出握手必须按队列顺序取出并逐字段比较。
-- AW/AR故意不比较id：AxiReorder会分配下游id，响应时再还原上游id。
local AUTO_PATHS = {
    { source = "mst_aw", sink = "slv_aw", fields = {
        "addr", "len", "size", "burst", "lock", "cache", "prot", "qos", "region",
    } },
    { source = "mst_ar", sink = "slv_ar", fields = {
        "addr", "len", "size", "burst", "lock", "cache", "prot", "qos", "region",
    } },
    { source = "mst_w", sink = "slv_w", fields = { "data", "strb", "last" } },
}

-- auto_pending按输出通道保存尚未观察到的期望事务。下游可以重排不同ID的
-- 请求或响应，因此这些记录不是FIFO队列：每次握手会按字段搜索匹配项。
local auto_pending = {}
-- 下游B/R响应携带的是AxiReorder分配的id。以下映射将其还原为原始上游id，
-- 用于检查响应没有被送到错误的上游事务。
